    DECLARE @编号 INT;
    DECLARE @姓名 NVARCHAR(50);

    --INSERT  @tt_v1_人员_带部门名
    SELECT  @编号 = 编号 ,
            @姓名 = 姓名
    FROM    dbo.人员
    WHERE   工号 = @工号
            AND 密码 = @密码;

    --IF ( EXISTS ( SELECT    1
    --              FROM      @tt_v1_人员_带部门名 ) )
    IF ( @编号 IS NOT NULL )
        BEGIN
            --DECLARE @tt_登录日志 tt_登录日志;
            --INSERT  @tt_登录日志
            --        ( 工号, 姓名, 登录时间 )
            --VALUES  ( @工号, @姓名, GETDATE() );
            --        --SELECT  工号 ,
            --        --        姓名 ,
            --        --        GETDATE()
            --        --FROM    @tt_v1_人员_带部门名;
            
            --EXEC dbo.sp_登录日志_增 @tt_登录日志; 
			
            SELECT  *
            FROM    v1_人员_带部门名
            WHERE   编号 = @编号;

            SELECT  *
            FROM    dbo.tfn_人员的权限(@工号)  ORDER BY 编号;
        END;

    ELSE
        THROW 50001,N'登录信息错误',1;

