CREATE PROC [dbo].[sp_流程_发起]
    (
      @流程模板编号 INT ,
      @项目编号 INT ,
      @发起人编号 INT
    )
AS
    SET XACT_ABORT ON;

    BEGIN TRAN;
--1 新建一个流程,状态为0;其中,状态>=0,项目编号相同的流程,只能有一个;触发器来保证
    INSERT  dbo.流程
            ( 流程模板编号, 项目编号, 发起人编号, 状态, 创建时间, 备注 )
    VALUES  ( @流程模板编号, @项目编号, @发起人编号, 0, GETDATE(), N'' );

--2 新建这个流程的第一个步骤,状态为0;操作人,执行时间这两个目前没得填
    INSERT  dbo.步骤
            ( 步骤模板编号 ,
              流程编号 ,
              状态 ,
              建立时间
            )
            SELECT  b.编号 ,
SCOPE_IDENTITY() ,
0 ,
GETDATE()
            FROM    dbo.流程模板 a
JOIN dbo.步骤模板 b ON a.编号 = b.流程模板编号
AND a.编号 = @流程模板编号
AND b.上级编号 = 0;
        
    SELECT  SCOPE_IDENTITY();
    COMMIT TRAN;

CREATE TRIGGER [dbo].[tr_流程] ON [dbo].[流程]
    FOR INSERT, UPDATE
AS
    DECLARE @message NVARCHAR(1000) = NULL;

    SELECT  @message = CONCAT('流程已存在:', a.流程模板编号, '-', a.项目编号)
    FROM    dbo.流程 a
            JOIN Inserted b ON a.编号 <> b.编号
AND a.项目编号 = b.项目编号
							   AND a.流程模板编号 = b.流程模板编号
AND a.状态 >= 0;
   
    IF ( @messageIS NOT NULL )
        BEGIN
           
            THROW 50001,@message,1;
            ROLLBACK;
            RETURN;
        END;

