CREATE PROC [dbo].[sp_流程_完成步骤]
    (
      @步骤编号 INT ,
      @状态 INT ,
      @操作人 INT ,
      @备注 NVARCHAR(1000)
    )
AS --当此步骤状态为0才能操作;
    IF ( NOT EXISTS ( SELECT    1
FROM      dbo.步骤
WHERE     编号 = @步骤编号
AND 状态 = 0 )
       )
        THROW 50001,N'此步骤不存在或已完成',1;

	--不能在步骤完成这个动作里,将步骤状态设为0;
    IF ( @状态 = 0 )
        THROW 50001,N'操作状态错误',1;

    IF ( NOT EXISTS ( SELECT    1
FROM      dbo.步骤 a
JOIN dbo.步骤模板 b ON a.编号 = @步骤编号
AND a.步骤模板编号 = b.编号
JOIN dbo.步骤类型状态 c ON b.步骤类型编号 = c.步骤类型编号
AND c.状态值 = @状态 )
       )
        THROW 50001,N'该步骤不存在指定的操作',1;

    DECLARE @步骤模板编号 INT;
    DECLARE @流程编号 INT;
    DECLARE @下一步骤编号 INT= 0;

    SELECT  @步骤模板编号 = 步骤模板编号 ,
            @流程编号 = 流程编号
    FROM    dbo.步骤
    WHERE   编号 = @步骤编号;

    SET XACT_ABORT ON;
    BEGIN TRAN;
--1 更新此步骤状态
    UPDATE  dbo.步骤
    SET     状态 = @状态 ,
            操作人编号 = @操作人 ,
            执行时间 = GETDATE() ,
            备注 = @备注
    WHERE   编号 = @步骤编号;

--如果状态为-1 则新生成一个第一步;同样操作人,时间不管
--流程状态不变
    IF ( @状态 = -1 )
        BEGIN
            INSERT  dbo.步骤
( 步骤模板编号 ,
流程编号 ,
状态 ,
建立时间
)
SELECT  c.编号 ,
b.编号 ,
0 ,
GETDATE()
FROM    dbo.步骤 a
JOIN 流程 b ON a.编号 = @步骤编号
AND a.流程编号 = b.编号
JOIN dbo.步骤模板 c ON b.流程模板编号 = c.流程模板编号
AND c.上级编号 = 0;
            SET @下一步骤编号 = SCOPE_IDENTITY();
        END;
--如果状态为-2 则终止整个流程
--流程状态变为-2
    IF ( @状态 = -2 )
        UPDATE  流程
        SET     状态 = -2
        WHERE   编号 = @流程编号;

--如果状态为1 则找下一步
    IF ( @状态 = 1 )
        BEGIN
            DECLARE @下一个步骤模板编号 INT;
			--这里应该先判断准入条件,以便判断是哪个下一步.
            SELECT  @下一个步骤模板编号 = 编号
            FROM    dbo.步骤模板
            WHERE   上级编号 = @步骤模板编号;
			--如果有下一步
            IF ( @下一个步骤模板编号 IS NOT NULL )
                BEGIN
INSERT  dbo.步骤
( 步骤模板编号, 流程编号, 状态, 建立时间 )
VALUES  ( @下一个步骤模板编号, @流程编号, 0, GETDATE() );
SET @下一步骤编号 = SCOPE_IDENTITY();
                END;
            ELSE --如果已经是最后一步
                BEGIN
UPDATE流程
SET     状态 = 1
WHERE   编号 = @流程编号;
                END;

        END;
    COMMIT TRAN;

    SELECT  @下一步骤编号;  -- = 0表示没有下一步了

